import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { clearSelectedProduct } from "../../redux/product/productSlice";

const ProductForm = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { id } = useParams();
  const { products, selectedProduct } = useSelector((state) => state.product);

  const [product, setProduct] = useState({
    name: "",
    description: "",
    price: "",
    stockQuantity: "",
  });

  useEffect(() => {
    if (id) {
      const existingProduct = products.find((p) => p.id === parseInt(id));
      if (existingProduct) setProduct(existingProduct);
    } else {
      dispatch(clearSelectedProduct());
    }
  }, [id, products, dispatch]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (id) await dispatch(updateProduct({ id, product }));
    else await dispatch(createProduct(product));
    navigate("/products");
  };

  return (
    <div className="container mt-4">
      <h2 className="card text-center mt-2 bg-light p-2">
        {id ? "Edit Product" : "Add New Product"}
      </h2>

      <form onSubmit={handleSubmit}>
        <div className="mt-3 card bg-light p-3">
          <div className="d-flex justify-content-center gap-3 mt-2">
            <div className="d-flex flex-column w-100">
              <label htmlFor="name" className="form-label fw-bold mb-1">
                Name
              </label>
              <input
                id="name"
                className="form-control rounded w-100 p-2"
                type="text"
                placeholder="Enter product name"
                value={product.name}
                onChange={(e) =>
                  setProduct({ ...product, name: e.target.value })
                }
              />
            </div>

            <div className="d-flex flex-column w-100">
              <label htmlFor="description" className="form-label fw-bold mb-1">
                Description
              </label>
              <input
                id="description"
                className="form-control rounded w-100 p-2"
                type="text"
                placeholder="Enter description"
                value={product.description}
                onChange={(e) =>
                  setProduct({ ...product, description: e.target.value })
                }
              />
            </div>
          </div>

          <div className="d-flex justify-content-center gap-3 mt-3">
            <div className="d-flex flex-column w-100">
              <label htmlFor="price" className="form-label fw-bold mb-1">
                Price
              </label>
              <input
                id="price"
                className="form-control rounded w-100 p-2"
                type="number"
                placeholder="Enter price"
                value={product.price}
                onChange={(e) =>
                  setProduct({ ...product, price: e.target.value })
                }
              />
            </div>

            <div className="d-flex flex-column w-100">
              <label
                htmlFor="stockQuantity"
                className="form-label fw-bold mb-1"
              >
                Stock Quantity
              </label>
              <input
                id="stockQuantity"
                className="form-control rounded w-100 p-2"
                type="number"
                placeholder="Enter stock quantity"
                value={product.stockQuantity}
                onChange={(e) =>
                  setProduct({ ...product, stockQuantity: e.target.value })
                }
              />
            </div>
          </div>
        </div>

        <div className="mt-2 text-end mt-3">
          <button type="submit" className="rounded btn btn-primary">
            Save
          </button>
        </div>
      </form>
    </div>
  );
};

export default ProductForm;
